import sqlite3
import hashlib
import hmac
import os
import json
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_session(token):
    """Verify session token using HMAC"""
    if not token:
        return None
    parts = token.split('.')
    if len(parts) != 2:
        return None
    payload, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return json.loads(bytes.fromhex(payload).decode())
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria - supports flexible querying"""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    session = verify_session(auth[7:])
    if not session:
        return jsonify({'error': 'invalid session'}), 401

    # Build search query from parameters
    username = request.args.get('username', '')
    email = request.args.get('email', '')
    role = request.args.get('role', '')
    sort_by = request.args.get('sort', 'username')

    db = get_db()

    # Construct WHERE clause dynamically
    conditions = []
    if username:
        conditions.append(f"username LIKE '%{username}%'")
    if email:
        conditions.append(f"email LIKE '%{email}%'")
    if role:
        conditions.append(f"role = '{role}'")

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Validate sort column against allowlist
    allowed_sorts = ['username', 'email', 'role', 'id']
    if sort_by not in allowed_sorts:
        sort_by = 'username'

    query = f"SELECT id, username, email, role FROM users WHERE {where_clause} ORDER BY {sort_by}"

    # Log the search for compliance
    db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
               ('user_search', f'query_by={session.get("user")}, params={request.args.to_dict()}'))
    db.commit()

    try:
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'search failed', 'detail': str(e)}), 400

@app.route('/api/users/<int:user_id>/apikey', methods=['POST'])
def rotate_api_key(user_id):
    """Generate new API key for user"""
    auth = request.headers.get('Authorization', '')
    session = verify_session(auth.replace('Bearer ', ''))
    if not session or session.get('role') != 'admin':
        return jsonify({'error': 'admin required'}), 403

    new_key = hashlib.sha256(os.urandom(32)).hexdigest()
    db = get_db()
    db.execute("UPDATE users SET api_key = ? WHERE id = ?", (new_key, user_id))
    db.commit()
    return jsonify({'api_key': new_key})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
